import sys, threading, random, time
sys.path.insert(0,'.')
sys.setswitchinterval(1e-6)          # maximise preemption; invariants must still hold
from src.scheduler import Scheduler
import logging; logging.disable(logging.CRITICAL)

viol = []
t0 = time.time()
for trial in range(40):
    s = Scheduler(workers=random.choice([1,2,4,8]))
    lock = threading.Lock(); ran = []
    def mk(i):
        def f():
            with lock: ran.append(i)
            if i % 37 == 0: raise RuntimeError("boom")
            return i
        return f
    ids = list(range(300))
    cancelled = set(); clock = threading.Lock()
    def submitter(part):
        for i in part:
            s.submit(i, mk(i), priority=random.randint(0,5))
    def canceller():
        for i in ids:
            if s.cancel(i):
                with clock: cancelled.add(i)
    ts = [threading.Thread(target=submitter, args=(ids[0::2],)),
          threading.Thread(target=submitter, args=(ids[1::2],)),
          threading.Thread(target=canceller), threading.Thread(target=canceller)]
    for t in ts: t.start()
    for t in ts: t.join()
    s.shutdown(wait=True)
    res = s.results()
    if len(ran) != len(set(ran)): viol.append((trial,"job ran twice"))
    if cancelled & set(ran): viol.append((trial,"cancelled job ran"))
    # results == jobs that ran and did not raise
    expect = {(i,i) for i in ran if i % 37}
    if set(res) != expect: viol.append((trial,f"results mismatch {len(res)} vs {len(expect)}"))
    if len(res) != len(set(res)): viol.append((trial,"duplicate result"))
    if any(t.is_alive() for t in s._threads): viol.append((trial,"worker alive after shutdown"))
    # every id is accounted for: ran xor cancelled-and-never-ran
    for i in ids:
        if i not in ran and i not in cancelled: viol.append((trial,f"job {i} vanished"))
print("trials done in %.1fs; violations:"%(time.time()-t0), viol[:10] or "NONE")
